}

package thanh.toan.duan1.fragment;

import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.appcompat.widget.SearchView;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import java.util.List;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.adapter.ProductAdapter;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProducts;
import thanh.toan.duan1.model.Product;

public class HomeFragment extends Fragment {
    private static final String TAG = "HomeFragment";
    private RecyclerView productsRecyclerView;
    private ProgressBar progressBar;
    private ProductAdapter adapter;
    private SearchView searchView;
    private String currentCategory = null;
    private String currentSearch = "";
    private Handler searchHandler;
    private Runnable searchRunnable;
    private static final int SEARCH_DELAY = 500; // 500ms delay

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_home, container, false);

        productsRecyclerView = view.findViewById(R.id.products_recycler_view);
        progressBar = view.findViewById(R.id.progress_bar);
        searchView = view.findViewById(R.id.search_view);

        if (productsRecyclerView != null) {
            productsRecyclerView.setLayoutManager(new LinearLayoutManager(getContext()));
            Log.d(TAG, "RecyclerView initialized");
        } else {
            Log.e(TAG, "RecyclerView is null!");
        }

        searchHandler = new Handler(Looper.getMainLooper());
        setupSearchView();
        loadProducts(null, "");

        return view;
    }

    private void setupSearchView() {
        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                currentSearch = query;
                loadProducts(currentCategory, query);
                return true;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                currentSearch = newText;

                // Remove previous search request
                if (searchRunnable != null) {
                    searchHandler.removeCallbacks(searchRunnable);
                }

                // Create new search request with delay
                searchRunnable = () -> loadProducts(currentCategory, newText);
                searchHandler.postDelayed(searchRunnable, SEARCH_DELAY);

                return true;
            }
        });
    }

    private void loadProducts(String category, String search) {
        progressBar.setVisibility(View.VISIBLE);
        Log.d(TAG, "Loading products - Category: " + category + ", Search: " + search);

        apiProducts api = ApiService.getApi(getContext()).create(apiProducts.class);
        Call<List<Product>> call = api.getAllProducts(category, search);

        call.enqueue(new Callback<List<Product>>() {
            @Override
            public void onResponse(Call<List<Product>> call, Response<List<Product>> response) {
                progressBar.setVisibility(View.GONE);
                Log.d(TAG, "Response received. Code: " + response.code());

                if (response.isSuccessful() && response.body() != null) {
                    List<Product> products = response.body();
                    Log.d(TAG, "Products count: " + products.size());

                    if (products.isEmpty()) {
                        Toast.makeText(getContext(), "No products found", Toast.LENGTH_SHORT).show();
                    } else {
                        Product firstProduct = products.get(0);
                        Log.d(TAG, "First product: " + firstProduct.getName());
                        Log.d(TAG, "Images: " + (firstProduct.getImages() != null ? firstProduct.getImages().size() : "null"));
                        Log.d(TAG, "Rating: " + firstProduct.getRating());
                        Log.d(TAG, "Reviews: " + (firstProduct.getReviews() != null ? firstProduct.getReviews().size() : "null"));
                    }

                    adapter = new ProductAdapter(getContext(), products);
                    productsRecyclerView.setAdapter(adapter);
                    Log.d(TAG, "Adapter set successfully");
                } else {
                    Log.e(TAG, "Response not successful or body is null");
                    Toast.makeText(getContext(), "Failed to load products", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<List<Product>> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                Log.e(TAG, "API Error: " + t.getMessage());
                t.printStackTrace();
                Toast.makeText(getContext(), "Error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        // Clean up handler
        if (searchHandler != null && searchRunnable != null) {
            searchHandler.removeCallbacks(searchRunnable);
        }
    }
}

package thanh.toan.duan1.fragment;

import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.appcompat.widget.SearchView;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.LinearLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.adapter.ProductAdapter;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiFavorite;
import thanh.toan.duan1.api.apiProducts;
import thanh.toan.duan1.model.Product;
import thanh.toan.duan1.request.WishlistResponse;

public class HomeFragment extends Fragment {
    private static final String TAG = "HomeFragment";
    private RecyclerView productsRecyclerView;
    private ProgressBar progressBar;
    private ProductAdapter adapter;
    private SearchView searchView;
    private String currentCategory = null;
    private String currentSearch = "";
    private Handler searchHandler;
    private Runnable searchRunnable;
    private static final int SEARCH_DELAY = 500; // 500ms delay

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_home, container, false);

        productsRecyclerView = view.findViewById(R.id.products_recycler_view);
        progressBar = view.findViewById(R.id.progress_bar);
        searchView = view.findViewById(R.id.search_view);

        if (productsRecyclerView != null) {
            productsRecyclerView.setLayoutManager(new LinearLayoutManager(getContext()));
            Log.d(TAG, "RecyclerView initialized");
        } else {
            Log.e(TAG, "RecyclerView is null!");
        }

        searchHandler = new Handler(Looper.getMainLooper());
        setupSearchView();
        loadProducts(null, "");

        return view;
    }

    private void setupSearchView() {
        searchView.setOnQueryTextListener(new SearchView.OnQueryTextListener() {
            @Override
            public boolean onQueryTextSubmit(String query) {
                currentSearch = query;
                loadProducts(currentCategory, query);
                return true;
            }

            @Override
            public boolean onQueryTextChange(String newText) {
                currentSearch = newText;

                // Remove previous search request
                if (searchRunnable != null) {
                    searchHandler.removeCallbacks(searchRunnable);
                }

                // Create new search request with delay
                searchRunnable = () -> loadProducts(currentCategory, newText);
                searchHandler.postDelayed(searchRunnable, SEARCH_DELAY);

                return true;
            }
        });
    }

    private void loadProducts(String category, String search) {
        progressBar.setVisibility(View.VISIBLE);
        Log.d(TAG, "Loading products - Category: " + category + ", Search: " + search);

        apiProducts api = ApiService.getApi(getContext()).create(apiProducts.class);
        Call<List<Product>> call = api.getAllProducts(category, search);

        call.enqueue(new Callback<List<Product>>() {
            @Override
            public void onResponse(Call<List<Product>> call, Response<List<Product>> response) {
                progressBar.setVisibility(View.GONE);
                Log.d(TAG, "Response received. Code: " + response.code());

                if (response.isSuccessful() && response.body() != null) {
                    List<Product> products = response.body();
                    Log.d(TAG, "Products count: " + products.size());

                    adapter = new ProductAdapter(getContext(), products);
                    productsRecyclerView.setAdapter(adapter);
                    Log.d(TAG, "Adapter set successfully");

                    // Fetch wishlist once and pass favorites to adapter
                    apiFavorite favApi = ApiService.getApi(getContext()).create(apiFavorite.class);
                    favApi.getWishlist().enqueue(new Callback<WishlistResponse>() {
                        @Override
                        public void onResponse(Call<WishlistResponse> call, Response<WishlistResponse> response) {
                            Set<String> favIds = new HashSet<>();
                            if (response.isSuccessful() && response.body() != null && response.body().getData() != null
                                    && response.body().getData().getWishlist() != null) {
                                for (Product p : response.body().getData().getWishlist()) {
                                    if (p != null && p.getId() != null) favIds.add(p.getId());
                                }
                            }
                            adapter.setFavorites(favIds);
                        }

                        @Override
                        public void onFailure(Call<WishlistResponse> call, Throwable t) {
                            // ignore - keep empty favorites
                        }
                    });


                } else {
                    Log.e(TAG, "Response not successful or body is null");
                    Toast.makeText(getContext(), "Failed to load products", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<List<Product>> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                Log.e(TAG, "API Error: " + t.getMessage());
                t.printStackTrace();
                Toast.makeText(getContext(), "Error: " + t.getMessage(), Toast.LENGTH_SHORT).show();
            }
        });
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        // Clean up handler
        if (searchHandler != null && searchRunnable != null) {
            searchHandler.removeCallbacks(searchRunnable);
        }
    }
}

package thanh.toan.duan1.fragment;

import android.annotation.SuppressLint;
import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.IntentFilter;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.localbroadcastmanager.content.LocalBroadcastManager;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProfile;
import thanh.toan.duan1.model.User;
import thanh.toan.duan1.ui.LoginActivity;

public class ProfileFragment extends Fragment {

    private TextView userNameTextView, userEmailTextView;
    private Button logoutButton;
    private Button btnEditProfile;
    private BroadcastReceiver profileReceiver;

    @SuppressLint("MissingInflatedId")
    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {

        View view = inflater.inflate(R.layout.fragment_profile, container, false);

        userNameTextView = view.findViewById(R.id.user_name_text_view);
        userEmailTextView = view.findViewById(R.id.user_email_text_view);
        logoutButton = view.findViewById(R.id.logout_button);
        btnEditProfile = view.findViewById(R.id.btn_edit_profile);

        loadUserInfo();
        setupLogout();

        // open edit screen
        btnEditProfile.setOnClickListener(v -> {
            requireActivity().getSupportFragmentManager()
                    .beginTransaction()
                    .replace(R.id.fragment_container, new EditProfileFragment())
                    .addToBackStack(null)
                    .commit();
        });

        // listen for profile updates
        profileReceiver = new BroadcastReceiver() {
            @Override
            public void onReceive(Context context, Intent intent) {
                loadUserInfo();
            }
        };
        LocalBroadcastManager.getInstance(requireContext())
                .registerReceiver(profileReceiver, new IntentFilter("profile_updated"));

        return view;
    }

    @Override
    public void onDestroyView() {
        super.onDestroyView();
        try {
            LocalBroadcastManager.getInstance(requireContext()).unregisterReceiver(profileReceiver);
        } catch (Exception ignored) {}
    }

    private void loadUserInfo() {
        apiProfile api = ApiService.getApi(getContext()).create(apiProfile.class);
        Call<User> call = api.getUserProfile();

        call.enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    User user = response.body();
                    userNameTextView.setText(user.getFullName() != null ? user.getFullName() : user.getUsername());
                    userEmailTextView.setText(user.getEmail() != null ? user.getEmail() : "");
                } else {
                    Toast.makeText(getContext(), "Không tải được thông tin!", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(getContext(), "Lỗi kết nối server!", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void setupLogout() {
        logoutButton.setOnClickListener(v -> {
            SharedPreferences prefs = getContext().getSharedPreferences("MyAppPrefs", Context.MODE_PRIVATE);
            prefs.edit().remove("token").apply();

            Intent intent = new Intent(getActivity(), LoginActivity.class);
            startActivity(intent);
            getActivity().finish();
        });
    }
}

package thanh.toan.duan1.fragment;

import android.content.Context;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProfile;
import thanh.toan.duan1.model.User;
import thanh.toan.duan1.ui.LoginActivity;

public class ProfileFragment extends Fragment {

    private TextView userNameTextView, userEmailTextView;
    private Button logoutButton;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater,
                             @Nullable ViewGroup container,
                             @Nullable Bundle savedInstanceState) {

        View view = inflater.inflate(R.layout.fragment_profile, container, false);

        userNameTextView = view.findViewById(R.id.user_name_text_view);
        userEmailTextView = view.findViewById(R.id.user_email_text_view);
        logoutButton = view.findViewById(R.id.logout_button);

        loadUserInfo();
        setupLogout();

        return view;
    }

    private void loadUserInfo() {
        apiProfile api = ApiService.getApi(getContext()).create(apiProfile.class);
        Call<User> call = api.getUserProfile();

        call.enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                if (response.isSuccessful() && response.body() != null) {
                    User user = response.body();
                    userNameTextView.setText(user.getFullName() != null ? user.getFullName() : user.getUsername());
                    userEmailTextView.setText(user.getEmail() != null ? user.getEmail() : "");
                } else {
                    Toast.makeText(getContext(), "Không tải được thông tin!", Toast.LENGTH_SHORT).show();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                Toast.makeText(getContext(), "Lỗi kết nối server!", Toast.LENGTH_SHORT).show();
            }
        });
    }

    private void setupLogout() {
        logoutButton.setOnClickListener(v -> {
            SharedPreferences prefs = getContext().getSharedPreferences("MyAppPrefs", Context.MODE_PRIVATE);
            prefs.edit().remove("token").apply();

            Intent intent = new Intent(getActivity(), LoginActivity.class);
            startActivity(intent);
            getActivity().finish();
        });
    }
}

package thanh.toan.duan1.fragment;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.IntentFilter;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.util.Log;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.LinearLayout;
import android.widget.ProgressBar;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.fragment.app.Fragment;
import androidx.recyclerview.widget.GridLayoutManager;
import androidx.recyclerview.widget.RecyclerView;

import com.google.gson.Gson;

import java.util.ArrayList;
import java.util.List;

import retrofit2.Call;
import retrofit2.Callback;
import retrofit2.Response;
import thanh.toan.duan1.R;
import thanh.toan.duan1.adapter.ProductAdapter;
import thanh.toan.duan1.api.ApiService;
import thanh.toan.duan1.api.apiProfile;
import thanh.toan.duan1.model.Product;
import thanh.toan.duan1.model.User;

public class WishlistFragment extends Fragment {
    private static final String TAG = "WishlistFragment";
    private RecyclerView wishlistRecyclerView;
    private ProgressBar progressBar;
    private LinearLayout emptyLayout;
    private ProductAdapter adapter;
    private List<Product> wishlistProducts;

    private BroadcastReceiver wishlistReceiver;

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.fragment_wishlist, container, false);

        initViews(view);
        setupRecyclerView();
        loadWishlist();

        return view;
    }

    private void initViews(View view) {
        wishlistRecyclerView = view.findViewById(R.id.wishlist_recycler_view);
        progressBar = view.findViewById(R.id.progress_bar);
        emptyLayout = view.findViewById(R.id.empty_layout);
    }

    private void setupRecyclerView() {
        // Dùng GridLayoutManager với 2 cột
        wishlistRecyclerView.setLayoutManager(new GridLayoutManager(getContext(), 2));
        wishlistProducts = new ArrayList<>();
        adapter = new ProductAdapter(getContext(), wishlistProducts);
        wishlistRecyclerView.setAdapter(adapter);
    }

    private void loadWishlist() {
        SharedPreferences prefs = requireContext().getSharedPreferences("MyAppPrefs", Context.MODE_PRIVATE);
        String token = prefs.getString("token", null);

        if (token == null) {
            Toast.makeText(getContext(), "Bạn cần đăng nhập để xem yêu thích", Toast.LENGTH_SHORT).show();
            showEmptyState();
            return;
        }

        progressBar.setVisibility(View.VISIBLE);
        wishlistRecyclerView.setVisibility(View.GONE);
        emptyLayout.setVisibility(View.GONE);

        apiProfile api = ApiService.getApi(getContext()).create(apiProfile.class);
        api.getUserProfile().enqueue(new Callback<User>() {
            @Override
            public void onResponse(Call<User> call, Response<User> response) {
                progressBar.setVisibility(View.GONE);

                if (response.isSuccessful() && response.body() != null) {
                    User user = response.body();

                    List<Product> products = new ArrayList<>();
                    List<?> rawWishlist = user.getWishlist();
                    if (rawWishlist != null) {
                        Gson gson = new Gson();
                        for (Object item : rawWishlist) {
                            if (item instanceof Product) {
                                products.add((Product) item);
                            } else {
                                try {
                                    String json = gson.toJson(item);
                                    Product p = gson.fromJson(json, Product.class);
                                    if (p != null) products.add(p);
                                } catch (Exception e) {
                                    Log.w(TAG, "Cannot parse wishlist item: " + e.getMessage());
                                }
                            }
                        }
                    }

                    if (!products.isEmpty()) {
                        wishlistProducts.clear();
                        wishlistProducts.addAll(products);
                        adapter.notifyDataSetChanged();
                        showWishlist();
                    } else {
                        showEmptyState();
                    }
                } else {
                    Toast.makeText(getContext(), "Không tải được danh sách yêu thích", Toast.LENGTH_SHORT).show();
                    showEmptyState();
                }
            }

            @Override
            public void onFailure(Call<User> call, Throwable t) {
                progressBar.setVisibility(View.GONE);
                Log.e(TAG, "API Error: " + t.getMessage());
                Toast.makeText(getContext(), "Lỗi kết nối: " + t.getMessage(), Toast.LENGTH_SHORT).show();
                showEmptyState();
            }
        });
    }

    private void showEmptyState() {
        wishlistRecyclerView.setVisibility(View.GONE);
        emptyLayout.setVisibility(View.VISIBLE);
    }

    private void showWishlist() {
        wishlistRecyclerView.setVisibility(View.VISIBLE);
        emptyLayout.setVisibility(View.GONE);
    }

    @Override
    public void onResume() {
        super.onResume();
        // Reload khi quay lại fragment
        loadWishlist();
    }

    // register receiver to refresh wishlist when other parts of app modify it
    @Override
    public void onStart() {
        super.onStart();
        wishlistReceiver = new BroadcastReceiver() {
            @Override
            public void onReceive(Context context, Intent intent) {
                String action = intent != null ? intent.getAction() : "<null>";
                Log.d(TAG, "Received broadcast action=" + action + ", reloading wishlist");
                // reload wishlist when receiving the update broadcast
                loadWishlist();
            }
        };
        // Register a system/local broadcast receiver for the app-wide action
        requireContext().registerReceiver(wishlistReceiver, new IntentFilter("thanh.toan.duan1.WISHLIST_UPDATED"));
    }

    @Override
    public void onStop() {
        super.onStop();
        try {
            requireContext().unregisterReceiver(wishlistReceiver);
        } catch (Exception ignored) {}
     }
}

